import { readFileSync } from "node:fs";
import jpeg from "jpeg-js";
import { describe, expect, it } from "vitest";
import { defaultWeights } from "../src/vision/default-weights.ts";
import { readBoard } from "../src/vision/read-board.ts";

// Fixtures are photos from the held-out eval set (fonts the classifier never saw), regenerated by
// `npm run gen`; two 3x3 and two 4x4 boards.
const FIXTURES = ["0008", "0000", "0001", "0019"];

describe("readBoard end to end", () => {
  for (const name of FIXTURES) {
    // Measured (Node 22, 4-core container): 0.8-2.1 s per photo. Timeout 10x the slowest (25 s): a
    // loaded machine took 5.6-8.7 s, past vitest's default 5 s.
    it(`reads photo ${name} exactly`, { timeout: 25_000 }, () => {
      const label = JSON.parse(
        readFileSync(new URL(`fixtures/photo-${name}.json`, import.meta.url), "utf8"),
      ) as { size: number; state: number[] };
      const decoded = jpeg.decode(
        readFileSync(new URL(`fixtures/photo-${name}.jpg`, import.meta.url)),
        { useTArray: true, formatAsRGBA: true },
      );
      const result = readBoard(
        { width: decoded.width, height: decoded.height, data: new Uint8ClampedArray(decoded.data) },
        defaultWeights,
      );
      if (result.status !== "accepted") throw new Error(`not accepted: ${result.message}`);
      expect(result.board.size).toBe(label.size);
      expect([...result.board.cells]).toEqual(label.state);
    });
  }

  it("finds no board in a blank image", () => {
    const data = new Uint8ClampedArray(200 * 150 * 4).fill(128);
    const result = readBoard({ width: 200, height: 150, data }, defaultWeights);
    expect(result.status).toBe("no-board");
  });

  it("throws a clear error when the RGBA buffer is shorter than width*height*4", () => {
    const data = new Uint8ClampedArray(200 * 150 * 4 - 1);
    expect(() => readBoard({ width: 200, height: 150, data }, defaultWeights)).toThrow(
      /RGBA buffer has 119999 bytes, expected 120000/,
    );
  });
});
